/// Whether `character` is punctuation or a symbol, Unicode category P or S.
pub(super) fn is_mark(character: char) -> bool {
    within(MARKS, character)
}

/// Whether `character` is category Mn, Me or Cf.
pub(super) fn is_joiner(character: char) -> bool {
    within(JOINERS, character)
}

fn within(table: &[(u32, u32)], character: char) -> bool {
    let scalar = u32::from(character);
    table
        .binary_search_by(|(first, last)| {
            if *last < scalar {
                std::cmp::Ordering::Less
            } else if *first > scalar {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}
